import pytesseract
from PIL import Image
import os
import re

def extract_date(text):
    patterns = [
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{4})',
        r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})',
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{2})\b',
    ]
    found_dates = []
    lines = text.split('\n')
    for line in lines:
        for pattern in patterns:
            matches = re.finditer(pattern, line)
            for match in matches:
                g = match.groups()
                try:
                    if len(g[2]) == 4:
                        d, m, y = int(g[0]), int(g[1]), int(g[2])
                        if 1 <= m <= 12 and 1 <= d <= 31:
                            dt = datetime(y, m, d)
                            found_dates.append(dt)
                    elif len(g[0]) == 4:
                        y, m, d = int(g[0]), int(g[1]), int(g[2])
                        if 1 <= m <= 12 and 1 <= d <= 31:
                            dt = datetime(y, m, d)
                            found_dates.append(dt)
                    elif len(g[2]) == 2:
                        d, m, y_short = int(g[0]), int(g[1]), int(g[2])
                        y = 2000 + y_short
                        if 1 <= m <= 12 and 1 <= d <= 31:
                            dt = datetime(y, m, d)
                            found_dates.append(dt)
                except: continue
        if found_dates: break
    if found_dates: return found_dates[0].strftime('%Y-%m-%d')
    return None

def extract_total(text):
    lines = text.split('\n')
    keywords = ['GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT']
    exclusion = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']
    amount_pattern = r'(\d{1,3}(?:[,\s]\d{3})*[\.\,]\s?\d{2})\b'

    for kw in keywords:
        for i, line in enumerate(lines):
            line_upper = line.upper()
            if kw in line_upper:
                is_excluded = False
                for ex in exclusion:
                    if ex in line_upper and ex not in kw:
                        is_excluded = True
                        break
                if is_excluded: continue

                match = re.search(amount_pattern, line)
                if match:
                    raw_val = match.group(1)
                    cleaned = re.sub(r'\s+', '', raw_val)
                    main_part = cleaned[:-3].replace(',', '').replace('.', '')
                    decimal_part = cleaned[-2:]
                    final_val = main_part + "." + decimal_part
                    return final_val, kw, line

                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    if not any(ex in next_line.upper() for ex in exclusion):
                        matches = re.findall(amount_pattern, next_line)
                        if matches:
                            raw_val = matches[-1]
                            cleaned = re.sub(r'\s+', '', raw_val)
                            main_part = cleaned[:-3].replace(',', '').replace('.', '')
                            decimal_part = cleaned[-2:]
                            final_val = main_part + "." + decimal_part
                            return final_val, kw, line + " | NEXT: " + next_line
    return None, None, None

