import pytesseract
from PIL import Image
import os
import re
from datetime import datetime
from openpyxl import Workbook

def clean_amount(raw_val):
    mapping = {
        'O': '0', 'I': '1', 'S': '5', 'Z': '2', 'B': '8', 'G': '9', 'U': '0', 'T': '1', 'L': '1',
        'u': '0', 'i': '1', 's': '5', 'z': '2', 'b': '8', 'g': '9', 'l': '1', 'o': '0'
    }

    # Find last separator
    sep_idx = -1
    for i, char in enumerate(raw_val):
        if char in '., ':
            sep_idx = i

    if sep_idx != -1:
        main_part_raw = raw_val[:sep_idx]
        decimal_part_raw = raw_val[sep_idx+1:]
    else:
        main_part_raw = raw_val[:-2]
        decimal_part_raw = raw_val[-2:]

    def convert(s):
        res = ""
        for c in s:
            if c.isdigit(): res += c
            elif c in mapping: res += mapping[c]
        return res

    main_part = convert(main_part_raw)
    decimal_part = convert(decimal_part_raw)

    if len(decimal_part) > 2:
        decimal_part = decimal_part[:2]
    elif len(decimal_part) == 1:
        decimal_part += "0"
    elif len(decimal_part) == 0:
        decimal_part = "00"

    if main_part:
        return f"{main_part}.{decimal_part}"
    return None

def extract_date(text):
    # Common date patterns
    patterns = [
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{4})',
        r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})',
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{2})\b',
        r'(\d{1,2})[\s](\d{1,2})[\s](\d{4})',
        r'(\d{8})\b', # DDMMYYYY
    ]

    lines = text.split('\n')
    for line in lines:
        for pattern in patterns:
            match = re.search(pattern, line)
            if match:
                g = match.groups()
                try:
                    if len(g) == 3:
                        if len(g[2]) == 4: # DD/MM/YYYY
                            d, m, y = int(g[0]), int(g[1]), int(g[2])
                        elif len(g[0]) == 4: # YYYY/MM/DD
                            y, m, d = int(g[0]), int(g[1]), int(g[2])
                        elif len(g[2]) == 2: # DD/MM/YY
                            d, m, y = int(g[0]), int(g[1]), 2000 + int(g[2])
                        else: continue
                    elif len(g) == 1: # DDMMYYYY
                        s = g[0]
                        d, m, y = int(s[:2]), int(s[2:4]), int(s[4:])
                    else: continue

                    # Basic validation and fix common OCR error in month (e.g. 62 -> 02)
                    if m > 12:
                        s_m = str(m)
                        if s_m.startswith('6'): m = int('0' + s_m[1:])

                    if 1 <= m <= 12 and 1 <= d <= 31:
                        return datetime(y, m, d).strftime('%Y-%m-%d')
                except: continue
    return None

def extract_total(text):
    lines = text.split('\n')
    keywords = [
        'GRAND TOTAL',
        'TOTAL RM',
        'TOTAL AMOUNT',
        'TOTAL DUE',
        'AMOUNT DUE',
        'BALANCE DUE',
        'NETT TOTAL',
        'NET TOTAL',
        'TOTAL',
        'AMOUNT'
    ]
    exclusion = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED', 'CASH']

    amount_pattern = r'(\d[\d\s,\.]*[\.,]\s?[0-9A-Za-z]{0,3})\b'

    for kw in keywords:
        # Search lines in reverse to find the final total
        for i in range(len(lines)-1, -1, -1):
            line = lines[i]
            line_upper = line.upper()
            if kw in line_upper:
                is_excluded = False
                for ex in exclusion:
                    if ex in line_upper and ex not in kw:
                        if "INCL" in line_upper or "TOTAL RM" in kw: pass
                        else:
                            is_excluded = True
                            break
                if is_excluded: continue

                matches = re.findall(amount_pattern, line)
                if matches:
                    val = clean_amount(matches[-1])
                    if val: return val

                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    if not any(ex in next_line.upper() for ex in exclusion):
                        matches = re.findall(amount_pattern, next_line)
                        if matches:
                            val = clean_amount(matches[-1])
                            if val: return val
    return None

def main():
    img_dir = 'dataset/img'
    files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])
    results = []
    for filename in files:
        path = os.path.join(img_dir, filename)
        try:
            text = pytesseract.image_to_string(Image.open(path))
            date = extract_date(text)
            total = extract_total(text)
            results.append((filename, date, total))
        except:
            results.append((filename, None, None))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for row in results:
        ws.append(row)
    wb.save('stat_ocr.xlsx')

if __name__ == "__main__":
    main()

